BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷256", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。引文按原文保留，疑似转录讹字单独注明。", "url": "https://github.com/greed-216/histree/blob/fdc81a0b21a4c29dcfb4a4ecc9006df86ffe9248/resources/derived/tongjian/256.txt", "note": "卷256中和四年21段；原始电子文本与SHA-256见来源清单。", "id": "a38849fc-5d04-59ee-ae04-1830b68b7d1a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李可举", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李可举。", "biography": null, "status": "draft", "id": "5aeffc3a-dd15-5cfe-9542-03dc6b5476dd"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "王处存", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王处存。", "biography": null, "status": "draft", "id": "8eb58bbe-206e-5b69-af3c-0dd5435bf54b"}, {"name": "赫连铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：赫连铎。", "biography": null, "status": "draft", "id": "b54a0fc9-ea29-5e0d-9d2a-f8fe5be8cda9"}, {"name": "李全忠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李全忠。", "biography": null, "status": "draft", "id": "e55cc67e-c400-5cd4-ae6f-d62cccb251c2"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "康君立", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：康君立。", "biography": null, "status": "draft", "id": "8e06ad56-4fa8-5126-9253-2edc90d6439c"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "秦宗言", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：秦宗言。", "biography": null, "status": "draft", "id": "6445c654-4b86-5900-a704-d230aec2db92"}, {"name": "田令孜", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的田令孜：担忧杨师立作乱。", "biography": null, "status": "draft", "id": "5080b636-4944-5887-afed-2195aeb4a567"}, {"name": "王重荣", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "biography": "晚唐河中节度使；882年朱温举同州归附，王重荣接纳并上奏。", "status": "draft", "id": "fc935d86-e44a-538d-b21b-6e28a8604116"}, {"name": "匡祐", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：匡祐。", "biography": null, "status": "draft", "id": "42b7df26-b12a-579f-9530-a897826d7646"}, {"name": "齐克让", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：齐克让。", "biography": null, "status": "draft", "id": "8057013d-29b8-5eda-906f-229edd92a8c4"}, {"name": "刘仁恭", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“李思安进攻幽州，被刘守光击退”中为卢龙节度使。", "biography": null, "status": "draft", "id": "b8f07571-c891-57ce-b69c-3e4a58148227"}, {"name": "王重盈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王重盈。", "biography": null, "status": "draft", "id": "04d3efcf-c998-55c8-b602-766123712a88"}, {"name": "李罕之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：李罕之。", "biography": null, "status": "draft", "id": "3a3944bf-1d15-5b41-8fde-e3f51fbe285c"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "常浚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：常浚。", "biography": null, "status": "draft", "id": "f2a3d938-9d11-585f-82ae-fc4c8b1ff3a8"}, {"name": "杨全玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：杨全玫。", "biography": null, "status": "draft", "id": "26ca8a59-b4cc-5d58-9386-1c99f62f3591"}, {"name": "卢彦威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：卢彦威。", "biography": null, "status": "draft", "id": "57740e74-d82d-506c-8996-dc6402924d88"}, {"name": "曹诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：曹诚。", "biography": null, "status": "draft", "id": "cd03fd24-c7a1-5874-8569-46e6abd18763"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李可举与王镕谋攻王处存", "start_year": 885, "end_year": 885, "time_original": "光启元年三月后条；具体日未载", "dynasty": "唐", "description": "李可举、王镕约定合攻王处存并分其地，又说赫连铎攻李克用后方。李可举遣李全忠攻易州，王镕遣兵攻无极；王处存向李克用求援，李克用遣康君立等援救。", "phases": [], "location_name": "易州、无极", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3a6ccbae-c1b2-5d29-ae3d-a0162ca2514d"}, {"title": "秦宗权遣弟秦宗言攻荆南", "start_year": 885, "end_year": 885, "time_original": "光启元年闰月", "dynasty": "唐", "description": "秦宗权遣弟秦宗言侵犯荆南。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0752921e-8e48-5f16-84b5-2362e1195851"}, {"title": "田令孜在蜀募新军", "start_year": null, "end_year": null, "time_original": "在蜀期间；确年待考", "dynasty": "唐", "description": "《通鉴》追叙田令孜在蜀募新军五十四都，分隶两神策军，由十军统辖。", "phases": [], "location_name": "蜀", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dd980f4a-c5e6-51f4-962f-5f7ab508aa84"}, {"title": "朝廷因藩镇截留税收难给军赏", "start_year": 885, "end_year": 885, "time_original": "光启元年闰月后条；具体月日未载", "dynasty": "唐", "description": "《通鉴》记藩镇各专租税，朝廷主要收京畿及同、华、凤翔等州租税，难以按时发军赏，士卒有怨言。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "1bda41bc-da4d-5492-80aa-a3020607b160"}, {"title": "王重荣在中和以来控制两池盐利", "start_year": null, "end_year": null, "time_original": "中和以来；具体起年待考", "dynasty": "唐", "description": "安邑、解县两池先前由盐铁官榷；中和以来王重荣控制其利，每年献盐三千车供国用。", "phases": [], "location_name": "安邑、解县两池", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1ccfd82e-b885-5c59-a814-333361e15f8c"}, {"title": "田令孜兼两池榷盐使，引发王重荣争论", "start_year": 885, "end_year": 885, "time_original": "光启元年夏四月", "dynasty": "唐", "description": "田令孜奏请两池盐利复归盐铁管辖，并于四月兼任两池榷盐使，以盐利供军；王重荣接连上章反对，中使劝谕未果。", "phases": [], "location_name": "安邑、解县两池", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d89b2424-b82e-5cb6-9605-0f087ad8f660"}, {"title": "匡祐出使河中，与王重荣部生冲突", "start_year": 885, "end_year": 885, "time_original": "光启元年五月前；具体日未载", "dynasty": "唐", "description": "田令孜养子匡祐出使河中，王重荣厚待而匡祐骄傲，军中不满；王重荣责备其无礼，监军调解，匡祐返回后劝田令孜对付王重荣。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cad22719-b292-5c4c-b31a-96acf327f746"}, {"title": "田令孜五月奏调王重荣、齐克让、王处存", "start_year": 885, "end_year": 885, "time_original": "光启元年五月", "dynasty": "唐", "description": "田令孜调王重荣为泰宁节度使、齐克让为义武节度使、王处存为河中节度使，并诏李克用援王处存赴镇；这是一组任命诏令，王重荣随后未依令赴任。", "phases": [], "location_name": "泰宁、义武、河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "27484f1d-3474-5747-a397-328f8d27a576"}, {"title": "刘仁恭穴地攻入易州", "start_year": 885, "end_year": 885, "time_original": "光启元年五月后条；具体日未载", "dynasty": "唐", "description": "卢龙军攻易州，刘仁恭掘地道入城并夺取易州。", "phases": [], "location_name": "易州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43653e8b-5894-5be1-90d8-578d546c3938"}, {"title": "李克用在无极、新城击败成德军", "start_year": 885, "end_year": 885, "time_original": "光启元年五月后条；具体日未载", "dynasty": "唐", "description": "李克用亲率军援无极，败成德军，再攻新城并追至九门；斩首数字依《通鉴》记述。", "phases": [], "location_name": "无极、新城、九门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "154a5614-dcf6-55a9-a7fa-2c230f9309dd"}, {"title": "王处存夜袭收复易州", "start_year": 885, "end_year": 885, "time_original": "李克用援无极之际；具体日未载", "dynasty": "唐", "description": "王处存命士卒披羊皮接近易州城，趁卢龙军出城掠取时攻击，收复易州，李全忠逃走。", "phases": [], "location_name": "易州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "aa2587af-daca-5eda-bb6e-d10615a62855"}, {"title": "王重盈加同平章事", "start_year": 885, "end_year": 885, "time_original": "光启元年五月后条；具体日未载", "dynasty": "唐", "description": "陕虢节度使王重盈加同平章事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "19dbba81-40d6-595f-953a-c137decf27d5"}, {"title": "李全忠败后袭幽州，李可举自焚", "start_year": 885, "end_year": 885, "time_original": "光启元年六月", "dynasty": "唐", "description": "李全忠败于易州后恐获罪，率残军返袭幽州。六月李可举陷入困境，举族登楼自焚，李全忠自称留后。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10b5bb3a-b005-5084-a7ac-a3c528c59caf"}, {"title": "李罕之弃东都，秦宗权部陷城", "start_year": 885, "end_year": 885, "time_original": "光启元年六月后条；相拒数月起点未载", "dynasty": "唐", "description": "李罕之与秦宗权将孙儒对峙数月，因兵少粮尽弃东都，西退渑池；《通鉴》记秦宗权军陷东都。", "phases": [], "location_name": "东都、渑池", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43b6899e-0911-5bb5-9c2c-59059eeb1ad1"}, {"title": "李全忠获任卢龙留后", "start_year": 885, "end_year": 885, "time_original": "光启元年七月", "dynasty": "唐", "description": "朝廷以李全忠为卢龙留后。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "88bb07c8-7271-5277-bab3-b05c82a6f378"}, {"title": "常浚上疏批评朝廷姑息藩镇", "start_year": 885, "end_year": 885, "time_original": "光启元年七月乙巳", "dynasty": "唐", "description": "右补阙常浚上疏，认为朝廷过于姑息藩镇，请整饬刑典。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "ffb4d80a-8fef-507a-9ea1-f42b44cd5302"}, {"title": "常浚被贬万州，后获赐死", "start_year": 885, "end_year": 885, "time_original": "七月庚戌贬；赐死在其后、确日未载", "dynasty": "唐", "description": "田令孜党人称常浚奏疏会激怒藩镇；常浚于庚戌被贬万州司户，不久被赐死。", "phases": [], "location_name": "万州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c56d8261-363f-5a3e-87aa-44eab0140d59"}, {"title": "沧州军逐杨全玫，推卢彦威留后", "start_year": 885, "end_year": 885, "time_original": "光启元年七月后条；具体日未载", "dynasty": "唐", "description": "沧州军变，逐节度使杨全玫，推牙将卢彦威为留后；杨全玫逃往幽州。", "phases": [], "location_name": "沧州、幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "27034717-9211-537d-ace7-d41a327c0d49"}, {"title": "朝廷任曹诚义昌、卢彦威德州", "start_year": 885, "end_year": 885, "time_original": "沧州军变后；具体日未载", "dynasty": "唐", "description": "朝廷任保銮都将曹诚为义昌节度使，任卢彦威为德州刺史；原文仅记任命，不说明二人是否赴任。", "phases": [], "location_name": "义昌、德州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "197b3393-333b-52a9-88f2-8367bae79a0a"}, {"title": "孙儒焚掠东都后撤走", "start_year": 885, "end_year": 885, "time_original": "据东都月余后；确月日未载", "dynasty": "唐", "description": "孙儒占东都一个多月后焚烧宫室、官寺、民居并大肆劫掠，随后离去。", "phases": [], "location_name": "东都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "85011fa0-a53e-515a-8995-c2f4539e8d3e"}, {"title": "李罕之返回东都", "start_year": 885, "end_year": 885, "time_original": "孙儒撤离后；确月日未载", "dynasty": "唐", "description": "孙儒撤走后，李罕之率众返回东都，于市西筑垒居住。", "phases": [], "location_name": "东都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "83201146-239a-52ad-924a-0c947827b3d8"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

